import { test } from "node:test";
import assert from "node:assert/strict";
import { Database } from "../src/db/database.ts";
import { Migrator, type Migration } from "../src/db/migrator.ts";
import { MIGRATIONS, prepareDatabase } from "../src/courses/schema.ts";

const now = () => new Date("2026-11-19T06:00:00Z");
// Main as it was before the add_enrollment_progress PR merged (5 and 6 merged first).
const withoutV4 = MIGRATIONS.filter((m) => m.version !== 4);

test("a fresh database gets every migration, in version order", async () => {
    const db = new Database();
    const applied = await new Migrator(db, MIGRATIONS, now).migrate();
    assert.deepEqual(applied, [
        "0001_create_courses",
        "0002_create_enrollments",
        "0003_add_course_language",
        "0004_add_enrollment_progress",
        "0005_create_certificates",
        "0006_add_course_slug",
    ]);
    assert.deepEqual(db.columns("courses"), ["id", "title", "published", "language", "slug"]);
});

test("running migrate again applies nothing", async () => {
    const db = new Database();
    await new Migrator(db, MIGRATIONS, now).migrate();
    assert.deepEqual(await new Migrator(db, MIGRATIONS, now).migrate(), []);
    assert.equal(db.select("schema_migrations").length, 6);
});

test("a migration merged after newer ones already ran is still applied", async () => {
    const db = new Database();
    await new Migrator(db, withoutV4, now).migrate();
    const applied = await new Migrator(db, MIGRATIONS, now).migrate();
    console.log("second deploy applied:", applied, "enrollments columns:", db.columns("enrollments"));
    assert.deepEqual(applied, ["0004_add_enrollment_progress"]);
    assert.ok(db.columns("enrollments").includes("progress_pct"));
});

test("status reports a late-merged migration as pending until it runs", async () => {
    const db = new Database();
    await new Migrator(db, withoutV4, now).migrate();
    const status = new Migrator(db, MIGRATIONS, now).status();
    assert.deepEqual(status.filter((s) => s.state === "pending").map((s) => s.id), ["0004_add_enrollment_progress"]);
});

test("the app refuses to boot while any migration is pending", async () => {
    const db = new Database();
    await prepareDatabase(db, { autoMigrate: true, now, migrations: withoutV4 });
    await assert.rejects(prepareDatabase(db, { autoMigrate: false, now }), /pending: 0004_add_enrollment_progress/);
});

test("a failing migration leaves no trace and stops the run", async () => {
    const db = new Database();
    const broken: Migration[] = [
        ...MIGRATIONS.slice(0, 2),
        {
            version: 3,
            name: "add_course_price",
            up(tx) {
                tx.addColumn("courses", "price_cents", 0);
                tx.addColumn("course", "currency", "EUR");
            },
        },
        MIGRATIONS[4],
    ];
    await assert.rejects(new Migrator(db, broken, now).migrate(), /0003_add_course_price failed: relation "course" does not exist/);
    assert.deepEqual(db.columns("courses"), ["id", "title", "published"]);
    assert.deepEqual(db.select("schema_migrations").map((r) => r.version), [1, 2]);
    assert.equal(db.hasTable("certificates"), false);
});

test("the slug migration backfills existing courses", async () => {
    const db = new Database();
    const migrator = new Migrator(db, MIGRATIONS.slice(0, 5), now);
    await migrator.migrate();
    db.insert("courses", { id: "c1", title: "Intro to SQL: Joins & Indexes", published: true, language: "pt" });
    await new Migrator(db, MIGRATIONS, now).migrate();
    assert.deepEqual(db.select("courses").map((c) => [c.slug, c.language]), [["intro-to-sql-joins-indexes", "pt"]]);
    assert.throws(() => new Migrator(db, [...MIGRATIONS, { version: 6, name: "dup", up() {} }], now), /duplicate/);
});
